CREATE TEMP TABLE region_repair_rows ON COMMIT DROP AS
SELECT e.id AS exercise_id, mr.id AS muscle_region_id, assignment.role
FROM exercises e JOIN region_repair r ON lower(r.name) = lower(e.name)
CROSS JOIN LATERAL (
  SELECT value AS slug, 'PRIMARY' AS role FROM jsonb_array_elements_text(r."primary")
  UNION ALL
  SELECT value, 'SECONDARY' FROM jsonb_array_elements_text(r."secondary")
) assignment
JOIN muscle_regions mr ON mr.slug = assignment.slug
WHERE e.created_by_user_id IS NULL;

CREATE TEMP TABLE region_repair_targets ON COMMIT DROP AS
SELECT DISTINCT wanted.exercise_id FROM region_repair_rows wanted
WHERE EXISTS (
  (SELECT muscle_region_id, role FROM region_repair_rows WHERE exercise_id = wanted.exercise_id
   EXCEPT SELECT muscle_region_id, role FROM exercise_muscle_regions WHERE exercise_id = wanted.exercise_id)
  UNION ALL
  (SELECT muscle_region_id, role FROM exercise_muscle_regions WHERE exercise_id = wanted.exercise_id
   EXCEPT SELECT muscle_region_id, role FROM region_repair_rows WHERE exercise_id = wanted.exercise_id)
);
DELETE FROM exercise_muscle_regions WHERE exercise_id IN (SELECT exercise_id FROM region_repair_targets);
INSERT INTO exercise_muscle_regions (exercise_id, muscle_region_id, role)
SELECT exercise_id, muscle_region_id, role FROM region_repair_rows
WHERE exercise_id IN (SELECT exercise_id FROM region_repair_targets);
DROP TABLE region_repair_targets;
DROP TABLE region_repair_rows;
DROP TABLE region_repair;

