DELETE FROM exercise_muscle_regions emr USING exercises e, region_repair r
WHERE emr.exercise_id = e.id AND lower(e.name) = lower(r.name) AND e.created_by_user_id IS NULL;

INSERT INTO exercise_muscle_regions (exercise_id, muscle_region_id, role)
SELECT e.id, mr.id, assignment.role
FROM exercises e JOIN region_repair r ON lower(r.name) = lower(e.name)
CROSS JOIN LATERAL (
  SELECT value AS slug, 'PRIMARY' AS role FROM jsonb_array_elements_text(r."primary")
  UNION ALL
  SELECT value, 'SECONDARY' FROM jsonb_array_elements_text(r."secondary")
) assignment
JOIN muscle_regions mr ON mr.slug = assignment.slug
WHERE e.created_by_user_id IS NULL AND (e.id = r.id OR lower(e.name) IN ('alternating hang clean', 'axle deadlift', 'back flyes - with bands', 'backward medicine ball throw', 'barbell deadlift', 'bench press', 'bench press - powerlifting', 'bench press with chains', 'bent over low-pulley side lateral', 'board press', 'box jump (multiple response)', 'box skip', 'cable deadlifts', 'cable face pull', 'car deadlift', 'carioca quick step', 'clean', 'clean deadlift', 'clean pull', 'clean and jerk', 'clean and press', 'clean from blocks', 'close-grip bench press', 'copenhagen plank', 'cuban press', 'dead hang', 'deadlift', 'deadlift with bands', 'deadlift with chains', 'deficit deadlift', 'double kettlebell alternating hang clean', 'double kettlebell snatch', 'double leg butt kick', 'dumbbell clean', 'dumbbell floor press', 'dumbbell rear delt fly', 'elliptical', 'farmer carry', 'floor press', 'floor press with chains', 'flutter kicks', 'front box jump', 'glute bridge hold', 'handstand hold', 'hang clean', 'hang clean - below the knees', 'hang snatch', 'hang snatch - below knees', 'hip flexion with band', 'hollow hold', 'hurdle hops', 'incline machine press', 'jump rope', 'kettlebell dead clean', 'kettlebell hang clean', 'kettlebell sumo high pull', 'kettlebell swing', 'kettlebell thruster', 'knee tuck jump', 'l-sit', 'lateral bound', 'lateral box jump', 'lateral cone hops', 'lunge pass through', 'lying dumbbell tricep extension', 'medicine ball scoop throw', 'mixed grip chin', 'muscle snatch', 'one arm chin-up', 'one arm floor press', 'one-arm kettlebell clean', 'one-arm kettlebell snatch', 'one-arm kettlebell split snatch', 'one-arm kettlebell swings', 'one-arm open palm kettlebell clean', 'one-arm side deadlift', 'open palm kettlebell clean', 'outdoor cycling', 'outdoor run', 'pallof press', 'pallof press with rotation', 'pin presses', 'power clean', 'power clean from blocks', 'power snatch', 'power snatch from blocks', 'rear delt fly', 'return push from stance', 'reverse band bench press', 'reverse band deadlift', 'reverse band sumo deadlift', 'reverse fly machine', 'reverse hyperextension', 'rickshaw deadlift', 'rowing machine', 'scapular pull-up', 'single leg butt kick', 'smith machine hang power clean', 'smith machine incline press', 'snatch', 'snatch deadlift', 'snatch pull', 'snatch from blocks', 'split clean', 'split snatch', 'stair climber', 'standing bent-over one-arm dumbbell triceps extension', 'standing low-pulley one-arm triceps extension', 'standing one-arm dumbbell triceps extension', 'stationary bike', 'sumo deadlift', 'sumo deadlift with bands', 'sumo deadlift with chains', 'superman hold', 'supine chest throw', 'swimming', 'trap bar deadlift', 'treadmill run', 'triceps pulldown', 'two-arm kettlebell clean', 'upright row', 'vertical swing', 'walking', 'wall sit', 'weighted dip'));
